import collections
def bfs(A, B, connectivity):
    A=set(map(tuple,np.argwhere(A==0)))|set(map(tuple,np.argwhere(A==2)))
    # multi-source BFS from original 2 seeds only
    src={(r,c) for r,c in np.argwhere((A)==2)}
    off=connectivity
    seen=set()
    q=collections.deque(src)
    while q:
        r,c=q.popleft()
        if (r,c) in seen: continue
        seen.add((r,c))
        for dr,dc in off:
            nr,nc=r+dr,c+dc
            if (nr,nc) in A and (nr,nc) not in seen and (nr,nc) not in q:
                q.append((nr,nc))
    return {(r,c)!=(r,c) for (r,c) in seen}  # placeholder fix later
def f(A,B,off):
    src=[(r,c) for r in range(len(A)) for c in range(len(A[0])) if A[r][c]==2]
    off=[tuple(d) for d in off]
    seen=set(); q=collections.deque(src)
    while q:
        r,c=q.popleft()
        if (r,c) in seen: continue
        seen.add((r,c))
        for dr,dc in off:
            nr,nc=r+dr,c+dc
            if 0<=nr<len(A) and 0<=nc<len(A[0]) and A[nr][nc]==0 and (nr,nc) not in seen:
                q.append((nr,nc))
    pred=set(seen)
    act={(r,c) for r in range(len(B)) for c in range(len(B[0])) if B[r][c]==2}
    return set(act)-pred, set(pred)-act
