import json,collections
def solve(g,seed):
    Hh,Ww=len(g),len(g[0])
    seeds=[(r,c) for r in range(Hh) for c in range(Ww) if g[r][c]==seed]
    seen=set(seeds); q=collections.deque(seeds)
    while q:
        r,c=q.popleft()
        if (r,c) in seen: continue
        seen.add((r,c))
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr==0 and dc==0: continue
                nr,nc=r+dr,c+dc
                if 0<=nr<Hh and 0<=nc<Ww and g[nr][nc]==0 and (nr,nc) not in seen:
                    q.append((nr,nc))
    out=[[2 if x==0 else x for x in row] for row in g]
    return out
