import collections
def solve(g):
    H,W=len(g),len(g[0])
    cnt=collections.Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    seed=min(cnt,key=lambda v: cnt[v]) if False else min([v for v in cnt if cnt[v]<5], default=None)
    A={(r,c) for r in range(H) for c in range(W) if g[r][c]==seed}
    seen=A; q=collections.deque(A)
    while q:
        r,c=q.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if (dr,dc)==(0,0): continue
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]==bg and (nr,nc) not in seen:
                    seen.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in g]
    for r,c in seen: out[r][c]=seed
    return out
