    # use ALL 8 dihedral variants; a translate counts if image ⊆ zeros ∪ A
    pred=set()
    for tr in [(lambda r,c:(r,c)),(lambda r,c:(-r,c)),(lambda r,c:(r,-c)),(lambda r,c:(-r,-c)),
               (lambda r,c:(c,r)),(lambda r,c:(-c,r)),(lambda r,c:(c,-r)),(lambda r,c:(-c,-r))]:
        B={tr(p,q) for p,q in A}
        mr=min(p for p,_ in B); mc=min(q for _,q in B)
        norm=frozenset((p-mr,q-mc) for p,q in B)
        for dr in range(-H,H+1):
            for dc in range(-W,W+1):
                u={(r+dr,c+dc) for r,c in norm}
                if all(0<=rr<H and 0<=cc<W for rr,cc in u) and all(gi[rr][cc]==0 or (rr,cc) in A for rr,cc in u):
                    pred|={p for p in u if gi[p[0]][p[1]]==0}
    out=[row[:] for row in gi]
    for r in range(H):
        for c in range(W):
            if gi[r][c]==0 and (r,c) in pred: out[r][c]=s
    return sum(out[r][c]!=go[r][c] for r in range(H) for c in range(W))
